# Let me analyze the pattern of colors by row
print("Row-by-row pixel counts:")
for r in range(len(grid)):
    row = grid[r]
    counts = defaultdict(int)
    for x in row:
        counts[x] += 1
    bg_cells = counts[4] if 4 in counts else 0
    non_bg_counts = {k: v for k, v in counts.items() if k != 4}
    if non_bg_counts:
        print(f"Row {r:2d}: bg={bg_cells:2d}, non-bg: {sorted(non_bg_counts.items())}")

# Let me try different normalization approaches
from collections import defaultdict

def normalize_to(grid, replacement):
    result = [[0]*len(grid[0]) for _ in range(len(grid))]
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            val = grid[r][c]
            if val == 4:
                result[r][c] = 4
            elif val in replacement:
                result[r][c] = replacement[0]  # Use first as representative
            else:
                result[r][c] = val
    return result

# Group 1: {3, 9} → 3
# Group 2: {5, 7} → 5  
# Group 3: {2} → 2
def normalize_v1(grid):
    result = [[0]*len(grid[0]) for _ in range(len(grid))]
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            val = grid[r][c]
            if val == 4:
                result[r][c] = 4
            elif val == 3 or val == 9:
                result[r][c] = 3
            elif val == 5 or val == 7:
                result[r][c] = 5
            else:
                result[r][c] = val
    return result

# Alternative: use second element
def normalize_v2(grid):
    result = [[0]*len(grid[0]) for _ in range(len(grid))]
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            val = grid[r][c]
            if val == 4:
                result[r][c] = 4
            elif val == 3 or val == 9:
                result[r][c] = 9
            elif val == 5 or val == 7:
                result[r][c] = 7
            else:
                result[r][c] = val
    return result

def print_normalized(name, grid):
    print(f"\n=== {name} ===")
    counts = defaultdict(int)
    for row in grid:
        for val in row:
            counts[val] += 1
    non_bg = sum(1 for row in grid for cell in row if cell != 4)
    print(f"Non-bg: {non_bg}, Counts: {dict(counts)}")

g1 = normalize_v1(grid)
g2 = normalize_v2(grid)
print_normalized("v1: {3,9}->3, {5,7}->5", g1)
print_normalized("v2: {3,9}->9, {5,7}->7", g2)

